      else { g.beginPath(); g.arc(bx, t, 3.2, 0, 7); g.fill(); g.fillStyle = 'rgba(255,255,255,0.7)'; g.beginPath(); g.arc(bx - 1, t - 1, 1, 0, 7); g.fill(); }
    }
